extern "C" int32_t tally_v1_counter_clamp(TallyCounter counter, VhSpan ranges, VhList *out,
                                          const VhAllocator *allocator) {
    return guard("tally_v1_counter_clamp", [&]() -> int32_t {
        tally::Counter *counter_object = counter_table().find(counter.bits);
        if (counter_object == nullptr) {
            return fail(vh::kInvalidHandle, "tally_v1_counter_clamp: counter is not a live Counter");
        }
        std::vector<tally::Range> ranges_values;
        ranges_values.reserve(static_cast<size_t>(ranges.size));
        for (const TallyRange &item : vh::Span<TallyRange>(ranges)) {
            ranges_values.push_back(tally::api::convert(item));
        }
        vh::Span<tally::Range> ranges_items(ranges_values.data(), ranges_values.size());
        if (vh::Status allowed = tally::api::allow(call_counter_clamp, *counter_object); !allowed.ok()) {
            return fail(std::move(allowed.error()));
        }
        auto returned = tally::api::counter_clamp(*counter_object, ranges_items);
        if (!returned.ok()) {
            return fail(std::move(returned.error()));
        }
        std::vector<TallyRange> converted;
        converted.reserve(returned.value().size());
        for (const auto &item : returned.value()) {
            converted.push_back(tally::api::convert(item));
        }
        if (vh::assign_result(out, allocator, converted) != 0) {
            last_error = "tally_v1_counter_clamp: the allocator could not hold the result";
            return VH_STATUS_OUT_OF_MEMORY;
        }
        return 0;
    });
}

